async function updateOrderStatus(orderId, newStatus) {
  try {
    const { error } = await sb
      .from('orders')
      .update({ status: newStatus })
      .eq('id', orderId);

    if (error) {
      console.error('Error updating status', error);
      alert('Could not update status – please try again.');
      return;
    }

    if (newStatus === 'completed') {
      try {
        const res = await fetch('https://order-backend-production.up.railway.app/settle-loyalty', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ order_id: orderId })
        });

        const data = await res.json();

        if (!data.ok) {
          console.warn('Loyalty settlement failed', data);
          alert('Order marked completed, but loyalty settlement failed. Please check logs.');
        } else {
          console.log('Loyalty settled:', data.loyalty);
        }
      } catch (err) {
        console.error('Loyalty settlement error', err);
        alert('Order marked completed, but loyalty settlement failed.');
      }
    }
  } catch (err) {
    console.error('Unexpected error updating status', err);
    alert('Unexpected error updating status');
  }
}

async function updateOrderStatus(orderId, newStatus) {
  try {
    const { error } = await supabase
      .from('orders')
      .update({ status: newStatus })
      .eq('id', orderId);

    if (error) {
      console.error('Kitchen: error updating status', error);
      return;
    }

    console.info('Kitchen: status updated', orderId, newStatus);
  } catch (err) {
    console.error('Kitchen: unexpected error updating status', err);
  }
}

